sql.where:
grades.published_yn = 'Y'

    and grades.teacher_user_id = #{criteria.effectiveTeacherUserId}


    and grades.completion_type_code = #{criteria.normalizedCompletionTypeCode}


    and grades.semester_code = #{criteria.normalizedSemesterCode}


    and grades.course_area_code = #{criteria.normalizedCourseAreaCode}

mapper.select:
select 


order by grades.evaluation_year desc, grades.teacher_user_id, grades.semester_code, grades.completion_type_code, grades.course_area_code
limit #{criteria.safeSize} offset #{criteria.offset}
